create table accounts (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, email varchar(255) not null unique, password_hash varchar(255) not null, display_name varchar(255));
create table organizations (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, name varchar(255));
create table members (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), user_id uuid references accounts(id), role varchar(255), status varchar(255), unique(organization_id,user_id));
create table invitations (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), email varchar(255), role varchar(255), token_hash varchar(255), expires_at timestamp with time zone, accepted boolean not null);
create table locations (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), name varchar(255), timezone varchar(255), unique(id,organization_id));
create table sops (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), title varchar(255), category varchar(255), status varchar(255), current_version_id uuid, draft text, unique(id,organization_id));
create table sop_versions (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), sop_id uuid references sops(id), version_number integer not null, title varchar(255), steps text, published_at timestamp with time zone, published_by uuid references accounts(id), unique(sop_id,version_number));
create table task_templates (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), location_id uuid references locations(id), name varchar(255), description text, category varchar(255), start_time varchar(255), duration_minutes integer not null, priority varchar(255), sop_id uuid references sops(id), assigned_user_id uuid references accounts(id), active boolean not null, recurrence text, prerequisites text, quantity numeric(38,2), unit varchar(255));
create table daily_plans (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), location_id uuid references locations(id), business_date date, status varchar(255), variables text, generated_at timestamp with time zone, unique(location_id,business_date));
create table daily_tasks (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), plan_id uuid references daily_plans(id), template_id uuid references task_templates(id), source_key varchar(255), assigned_user_id uuid references accounts(id), sop_version_id uuid references sop_versions(id), title varchar(255), description text, priority varchar(255), planned_start_at timestamp with time zone, planned_end_at timestamp with time zone, suggested_quantity numeric(38,2), planned_quantity numeric(38,2), actual_quantity numeric(38,2), unit varchar(255), status varchar(255), quantity_locked boolean not null, completed_at timestamp with time zone, confirmations text, prerequisites text, unique(plan_id,source_key));
create table automation_rules (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), location_id uuid references locations(id), name varchar(255), priority integer not null, enabled boolean not null, condition_json text, action_json text);
create table variable_definitions (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), variable_key varchar(255), name varchar(255), unit varchar(255), value_type varchar(255), unique(organization_id,variable_key));
create table execution_logs (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), task_id uuid references daily_tasks(id), actor_id uuid references accounts(id), action varchar(255), request_key varchar(255), details text, unique(organization_id,request_key));
create table handovers (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), location_id uuid references locations(id), business_date date, author_id uuid references accounts(id), recipient_id uuid references accounts(id), content text);
create table audit_logs (id uuid primary key, created_at timestamp with time zone not null, revision bigint not null, organization_id uuid not null references organizations(id), actor_id uuid references accounts(id), action varchar(255), resource_id uuid, details text);
create index idx_members_org on members(organization_id);
create index idx_invitations_org on invitations(organization_id);
create index idx_locations_org on locations(organization_id);
create index idx_sops_org on sops(organization_id);
create index idx_sop_versions_org on sop_versions(organization_id);
create index idx_task_templates_org on task_templates(organization_id);
create index idx_daily_plans_org on daily_plans(organization_id);
create index idx_daily_tasks_org on daily_tasks(organization_id);
create index idx_automation_rules_org on automation_rules(organization_id);
create index idx_variable_definitions_org on variable_definitions(organization_id);
create index idx_execution_logs_org on execution_logs(organization_id);
create index idx_handovers_org on handovers(organization_id);
create index idx_audit_logs_org on audit_logs(organization_id);
create index idx_task_plan on daily_tasks(plan_id,planned_start_at);
create index idx_log_task on execution_logs(task_id,created_at);
alter table sops add constraint fk_current_version foreign key(current_version_id) references sop_versions(id);
